-- GeoNames data, CC BY attribution: https://www.geonames.org/
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
PRAGMA defer_foreign_keys = ON;
CREATE TABLE country (
  geoname_id INTEGER PRIMARY KEY, iso2 TEXT NOT NULL UNIQUE, iso3 TEXT,
  iso_numeric TEXT, name TEXT NOT NULL, capital TEXT, area_sq_km REAL,
  population INTEGER, continent TEXT, tld TEXT, currency_code TEXT,
  currency_name TEXT, phone TEXT, postal_code_format TEXT,
  postal_code_regex TEXT, languages TEXT, neighbours TEXT,
  equivalent_fips_code TEXT
);

CREATE TABLE state (
  geoname_id INTEGER PRIMARY KEY,
  country_iso2 TEXT NOT NULL REFERENCES country(iso2),
  admin1_code TEXT NOT NULL, name TEXT NOT NULL, ascii_name TEXT,
  latitude REAL, longitude REAL,
  UNIQUE(country_iso2, admin1_code)
);

CREATE TABLE municipality (
  geoname_id INTEGER PRIMARY KEY,
  country_iso2 TEXT NOT NULL REFERENCES country(iso2),
  state_geoname_id INTEGER NOT NULL REFERENCES state(geoname_id),
  admin2_code TEXT NOT NULL, name TEXT NOT NULL, ascii_name TEXT,
  latitude REAL, longitude REAL,
  UNIQUE(state_geoname_id, admin2_code)
);

CREATE INDEX idx_municipality_state ON municipality(state_geoname_id);
CREATE INDEX idx_state_country ON state(country_iso2);
COMMIT;
